        forall|rid| #[trigger]
            updates1.contains_key(rid) ==> updates1[rid].is_Placed() && logIndexLower
                <= updates1[rid].get_Placed_idx() < logIndexUpper ==> updates2.contains_key(rid)
                && updates2[rid] === updates1[rid],
    ensures
        LogRangeMatchesQueue(
            queue,
            log,
            queueIndex,
            logIndexLower,
            logIndexUpper,
            nodeId,
            updates2,
