#[inductive(readonly_apply)]
fn readonly_apply_inductive(pre: Self, post: Self, rid: ReqId) {
    assert(post.inv_read_results()) by {
        assert forall |rid2: ReqId| (#[trigger] post.local_reads.contains_key(rid2))
            implies post.read_results_match(post.local_reads[rid2]) by {
            if rid2 == rid {
                // The read was in ReadyToRead state before the transition
                let node_id = pre.local_reads[rid].get_ReadyToRead_node_id();
                let op = pre.local_reads[rid].get_ReadyToRead_op();
                let version_upper_bound = pre.local_reads[rid].get_ReadyToRead_version_upper_bound();
                let state = pre.replicas[node_id];
                let ret = DT::dispatch_spec(state, op);

                // Witness: v = local_versions[node_id]
                let v = pre.local_versions[node_id];

                // From wf_readstate for ReadyToRead:
                // version_upper_bound <= pre.current_local_version(node_id)
                // Since combiner[node_id] == Ready, current_local_version = local_versions[node_id]
                assert(pre.wf_readstate(pre.local_reads[rid]));
                assert(pre.combiner[node_id] == CombinerState::Ready);
                assert(pre.current_local_version(node_id) == pre.local_versions[node_id]);
                assert(version_upper_bound <= v);

                // From inv_local_version_upper_bound_heads:
                assert(v <= pre.version_upper_bound);
                // post.version_upper_bound == pre.version_upper_bound (unchanged)
                assert(v <= post.version_upper_bound);

                // rangeincl(version_upper_bound, v, post.version_upper_bound)
                assert(rangeincl(version_upper_bound, v, post.version_upper_bound));

                // From replica_state invariant:
                // state == compute_nrstate_at_version(pre.log, v)
                assert(pre.replica_state());
                assert(pre.replicas[node_id] == compute_nrstate_at_version(pre.log, pre.current_local_version(node_id)));
                assert(state == compute_nrstate_at_version(pre.log, v));

                // post.log == pre.log (readonly_apply doesn't change the log)
                assert(post.log == pre.log);
                assert(compute_nrstate_at_version(post.log, v) == compute_nrstate_at_version(pre.log, v));
                assert(ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op));

                // post.local_reads[rid] = Done { op, node_id, version_upper_bound, ret }
                assert(post.local_reads[rid] == ReadonlyState::Done {
                    op,
                    node_id,
                    version_upper_bound,
                    ret,
