    #[inductive(readonly_apply)]
    fn readonly_apply_inductive(pre: Self, post: Self, rid: ReqId) {
        // Extract read state components from pre
        let rs = pre.local_reads[rid];
        assert(rs.is_ReadyToRead()) by {
            // This follows from the transition requirement
        };
        let node_id = rs.get_ReadyToRead_node_id();
        let op = rs.get_ReadyToRead_op();
        let version_upper_bound = rs.get_ReadyToRead_version_upper_bound();
        let state = pre.replicas[node_id];
        let ret = DT::dispatch_spec(state, op);

        // Key witnesses for the proof
        let v = pre.local_versions[node_id];

        // Step 1: From wf_readstate for ReadyToRead + inv_local_version_upper_bound_heads:
        // version_upper_bound <= v (= local_versions[node_id]) <= version_upper_bound
        assert(pre.wf_readstate(rs));
        assert(pre.combiner[node_id].is_Ready());
        assert(pre.current_local_version(node_id) == pre.local_versions[node_id]);
        assert(version_upper_bound <= v);
        assert(v <= pre.version_upper_bound);

        // Step 2: From replica_state: state == compute_nrstate_at_version(pre.log, v)
        assert(pre.replicas[node_id] == compute_nrstate_at_version(pre.log, pre.current_local_version(node_id)));
        assert(state == compute_nrstate_at_version(pre.log, v));

        // Step 3: post has same log and version_upper_bound
        assert(post.log == pre.log);
        assert(post.version_upper_bound == pre.version_upper_bound);
        assert(v <= post.version_upper_bound);
        assert(rangeincl(version_upper_bound, v, post.version_upper_bound));
        assert(state == compute_nrstate_at_version(post.log, v));
        assert(ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op));

        // Step 4: post.local_reads[rid] is Done with the right values
        assert(post.local_reads[rid] == ReadonlyState::Done::<DT> { op, node_id, version_upper_bound, ret });

        // Step 5: prove inv_read_results for post
        assert(post.inv_read_results()) by {
            assert forall |rid2: ReqId| (#[trigger] post.local_reads.contains_key(rid2))
                implies post.read_results_match(post.local_reads[rid2]) by {
                if rid2 == rid {
                    // The new Done read - provide explicit witness
                    assert(post.local_reads[rid2] == ReadonlyState::Done::<DT> { op, node_id, version_upper_bound, ret });
                    assert(exists |v2: nat|
                        (#[trigger] rangeincl(version_upper_bound, v2, post.version_upper_bound))
                        && ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v2), op)) by {
                        assert(rangeincl(version_upper_bound, v, post.version_upper_bound));
                        assert(ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op));
                    };
                    assert(post.read_results_match(post.local_reads[rid2]));
                } else {
                    // Other reads are unchanged - transfer from pre
                    assert(pre.local_reads.contains_key(rid2));
                    assert(post.local_reads[rid2] == pre.local_reads[rid2]);

                    // Only Done reads need the existential
                    if pre.local_reads[rid2].is_Done() {
                        let ret2 = pre.local_reads[rid2].get_Done_ret();
                        let vub2 = pre.local_reads[rid2].get_Done_version_upper_bound();
                        let op2 = pre.local_reads[rid2].get_Done_op();

                        // Get the existential from pre invariant
                        assert(exists |vw: nat|
                            (#[trigger] rangeincl(vub2, vw, pre.version_upper_bound))
                            && ret2 == DT::dispatch_spec(compute_nrstate_at_version(pre.log, vw), op2)) by {
                            assert(pre.read_results_match(pre.local_reads[rid2]));
                        };

                        // Extract the witness
                        let v_w = choose |vw: nat|
                            (#[trigger] rangeincl(vub2, vw, pre.version_upper_bound))
                            && ret2 == DT::dispatch_spec(compute_nrstate_at_version(pre.log, vw), op2);

                        // Transfer witness to post (same log and version_upper_bound)
                        assert(rangeincl(vub2, v_w, pre.version_upper_bound));
                        assert(ret2 == DT::dispatch_spec(compute_nrstate_at_version(pre.log, v_w), op2));
                        assert(rangeincl(vub2, v_w, post.version_upper_bound));
                        assert(compute_nrstate_at_version(post.log, v_w) == compute_nrstate_at_version(pre.log, v_w));
                        assert(ret2 == DT::dispatch_spec(compute_nrstate_at_version(post.log, v_w), op2));

                        assert(exists |vw: nat|
                            (#[trigger] rangeincl(vub2, vw, post.version_upper_bound))
                            && ret2 == DT::dispatch_spec(compute_nrstate_at_version(post.log, vw), op2));

                        assert(post.local_reads[rid2] == ReadonlyState::Done::<DT> {
                            ret: ret2, version_upper_bound: vub2, op: op2,
                            node_id: pre.local_reads[rid2].get_Done_node_id()
                        });
                        assert(post.read_results_match(post.local_reads[rid2]));
                    } else {
                        // Non-Done reads: read_results_match = true
                        assert(post.read_results_match(post.local_reads[rid2]));
                    }
                }
            };
        };
    }
