    #[inductive(readonly_apply)]
    fn readonly_apply_inductive(pre: Self, post: Self, rid: ReqId) {
        // Extract read state components from pre
        let rs = pre.local_reads[rid];
        assert(rs.is_ReadyToRead()) by {
            // This follows from the transition requirement
        };
        let node_id = rs.get_ReadyToRead_node_id();
        let op = rs.get_ReadyToRead_op();
        let version_upper_bound = rs.get_ReadyToRead_version_upper_bound();
        let state = pre.replicas[node_id];
        let ret = DT::dispatch_spec(state, op);

        // Key witnesses for the proof
        let v = pre.local_versions[node_id];

        // Step 1: From wf_readstate for ReadyToRead + inv_local_version_upper_bound_heads:
        // version_upper_bound <= v (= local_versions[node_id]) <= version_upper_bound
        assert(pre.wf_readstate(rs));
        assert(pre.combiner[node_id].is_Ready());
        assert(pre.current_local_version(node_id) == pre.local_versions[node_id]);
        assert(version_upper_bound <= v);
        assert(v <= pre.version_upper_bound);

        // Step 2: From replica_state: state == compute_nrstate_at_version(pre.log, v)
        assert(pre.replicas[node_id] == compute_nrstate_at_version(pre.log, pre.current_local_version(node_id)));
        assert(state == compute_nrstate_at_version(pre.log, v));

        // Step 3: post has same log and version_upper_bound
        assert(post.log == pre.log);
        assert(post.version_upper_bound == pre.version_upper_bound);
        assert(v <= post.version_upper_bound);
        assert(rangeincl(version_upper_bound, v, post.version_upper_bound));
