                            (#[trigger] rangeincl(vub2, vw, pre.version_upper_bound))
                            && ret2 == DT::dispatch_spec(compute_nrstate_at_version(pre.log, vw), op2)) by {
                            assert(pre.read_results_match(pre.local_reads[rid2]));
                        };
                        let v_w = choose |vw: nat|
                            (#[trigger] rangeincl(vub2, vw, pre.version_upper_bound))
                            && ret2 == DT::dispatch_spec(compute_nrstate_at_version(pre.log, vw), op2);
                        assert(rangeincl(vub2, v_w, pre.version_upper_bound));
                        assert(ret2 == DT::dispatch_spec(compute_nrstate_at_version(pre.log, v_w), op2));
                        // Transfer to post
                        assert(rangeincl(vub2, v_w, post.version_upper_bound));
                        assert(compute_nrstate_at_version(post.log, v_w) == compute_nrstate_at_version(pre.log, v_w));
                        assert(ret2 == DT::dispatch_spec(compute_nrstate_at_version(post.log, v_w), op2));
                        assert(post.local_reads[rid2] == ReadonlyState::Done::<DT> {
                            op: op2, version_upper_bound: vub2, node_id: nid2, ret: ret2
                        });
                        assert(exists |vw: nat|
                            (#[trigger] rangeincl(vub2, vw, post.version_upper_bound))
                            && ret2 == DT::dispatch_spec(compute_nrstate_at_version(post.log, vw), op2));
                    }
                    _ => {
                        // Non-Done reads: trivially true
